                    <td className="px-4 py-3 text-[12px] text-[#85B7EB] dark:text-[#4A6FA5]">
                      {new Date(u.created_at).toLocaleDateString('tr-TR')}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

