import { useEffect, useState } from 'react';
import type { Task, TaskStatus } from '../types';
import { tasksApi } from '../api/tasks';
import { Header } from '../components/layout/Header';
import { StatusBadge } from '../components/ui/Badge';
import { TaskModal } from '../components/tasks/TaskModal';
import { Pencil, Trash2, Search } from 'lucide-react';

const STATUS_FILTERS: { value: TaskStatus | 'all'; label: string }[] = [
  { value: 'all', label: 'Tümü' },
  { value: 'todo', label: 'Yapılacak' },
  { value: 'in_progress', label: 'Devam Eden' },
  { value: 'done', label: 'Tamamlandı' },
];

export function TasksPage() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<TaskStatus | 'all'>('all');
  const [search, setSearch] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>();

  const fetchTasks = async () => {
    try {
      const data = await tasksApi.getAll();
      setTasks(data);
    } catch {}
    setLoading(false);
  };

  useEffect(() => { fetchTasks(); }, []);

  const openCreate = () => { setEditingTask(undefined); setModalOpen(true); };
  const openEdit = (task: Task) => { setEditingTask(task); setModalOpen(true); };

  const handleSave = async (data: { title: string; description: string; status: TaskStatus }) => {
    if (editingTask) {
      const updated = await tasksApi.update(editingTask.id, data);
      setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
    } else {
      const created = await tasksApi.create(data);
      setTasks((prev) => [...prev, created]);
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm('Bu görevi silmek istiyor musunuz?')) return;
    await tasksApi.delete(id);
    setTasks((prev) => prev.filter((t) => t.id !== id));
  };

  const filtered = tasks.filter((t) => {
    if (filter !== 'all' && t.status !== filter) return false;
    if (search && !t.title.toLowerCase().includes(search.toLowerCase())) return false;
    return true;
  });

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <Header title="Görevler" showNewTask onNewTask={openCreate} />

      <div className="flex-1 overflow-auto p-5">
        {/* Filters */}
        <div className="flex items-center gap-3 mb-4">
          <div className="relative flex-1 max-w-xs">
            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#85B7EB]" />
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Görev ara..."
              className="w-full pl-8 pr-3 py-2 bg-white dark:bg-[#122040] border border-[#B5D4F4] dark:border-[#1E3A5F] rounded-lg text-[13px] text-[#0C447C] dark:text-[#E8F1FF] placeholder-[#85B7EB] outline-none focus:border-[#3B82F6] transition-colors"
            />
          </div>
          <div className="flex gap-1">
            {STATUS_FILTERS.map((f) => (
              <button
                key={f.value}
                onClick={() => setFilter(f.value)}
                className={`px-3 py-1.5 rounded-lg text-[12px] font-medium transition-colors ${
                  filter === f.value
                    ? 'bg-[#3B82F6] text-white'
                    : 'bg-white dark:bg-[#122040] border border-[#B5D4F4] dark:border-[#1E3A5F] text-[#185FA5] dark:text-[#7BA3D4] hover:border-[#3B82F6]'
                }`}
              >
                {f.label}
              </button>
            ))}
          </div>
        </div>

        {/* Table */}
        <div className="bg-white dark:bg-[#122040] border border-[#B5D4F4] dark:border-[#1E3A5F] rounded-xl overflow-hidden">
          <table className="w-full">
            <thead>
              <tr className="border-b border-[#B5D4F4] dark:border-[#1E3A5F]">
                <th className="text-left px-4 py-3 text-[12px] font-medium text-[#185FA5] dark:text-[#7BA3D4]">Başlık</th>
                <th className="text-left px-4 py-3 text-[12px] font-medium text-[#185FA5] dark:text-[#7BA3D4]">Açıklama</th>
                <th className="text-left px-4 py-3 text-[12px] font-medium text-[#185FA5] dark:text-[#7BA3D4]">Durum</th>
                <th className="text-left px-4 py-3 text-[12px] font-medium text-[#185FA5] dark:text-[#7BA3D4]">Oluşturulma</th>
                <th className="px-4 py-3" />
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan={5} className="text-center py-8 text-[13px] text-[#85B7EB]">Yükleniyor...</td>
                </tr>
              ) : filtered.length === 0 ? (
                <tr>
                  <td colSpan={5} className="text-center py-8 text-[13px] text-[#85B7EB]">Görev bulunamadı.</td>
                </tr>
              ) : (
                filtered.map((task) => (
                  <tr key={task.id} className="border-b border-[#B5D4F4]/50 dark:border-[#1E3A5F]/50 hover:bg-[#F0F7FF] dark:hover:bg-[#0D1B2E]/50 transition-colors">
                    <td className="px-4 py-3 text-[13px] font-medium text-[#0C447C] dark:text-[#E8F1FF]">{task.title}</td>
                    <td className="px-4 py-3 text-[12px] text-[#378ADD] dark:text-[#7BA3D4] max-w-xs">
                      <span className="line-clamp-1">{task.description}</span>
                    </td>
                    <td className="px-4 py-3"><StatusBadge status={task.status} /></td>
                    <td className="px-4 py-3 text-[12px] text-[#85B7EB] dark:text-[#4A6FA5]">
                      {new Date(task.createdAt).toLocaleDateString('tr-TR')}
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex items-center justify-end gap-1">
                        <button onClick={() => openEdit(task)} className="p-1.5 rounded text-[#85B7EB] hover:text-[#3B82F6] transition-colors">
                          <Pencil size={13} />
                        </button>
                        <button onClick={() => handleDelete(task.id)} className="p-1.5 rounded text-[#85B7EB] hover:text-red-500 transition-colors">
                          <Trash2 size={13} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {modalOpen && (
        <TaskModal
          task={editingTask}
          onClose={() => setModalOpen(false)}
          onSave={handleSave}
        />
      )}
    </div>
  );
}

import fs from "fs";
import path from "path";

import { db } from "../config/db";

const getTableColumns = (tableName: string): Promise<string[]> => {
  return new Promise((resolve, reject) => {
    db.all(`PRAGMA table_info(${tableName})`, [], (err, rows: any[]) => {
      if (err) {
        reject(err);
        return;
      }

      resolve(rows.map((row) => String(row.name)));
    });
  });
};

const exec = (sql: string): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.exec(sql, (err) => {
      if (err) {
        reject(err);
        return;
      }

      resolve();
    });
  });
};

const syncRevokedTokensTable = async (): Promise<void> => {
  const columns = await getTableColumns("revoked_tokens");

  if (columns.length === 0) {
    return;
  }

  const expectedColumns = ["id", "token_hash", "created_at"];
  const isAlreadySynced =
    columns.length === expectedColumns.length &&
    expectedColumns.every((column, index) => columns[index] === column);

  if (isAlreadySynced) {
    return;
  }

  await exec(`
    BEGIN TRANSACTION;

    CREATE TABLE IF NOT EXISTS revoked_tokens_new (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      token_hash TEXT NOT NULL UNIQUE,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

    INSERT OR IGNORE INTO revoked_tokens_new (id, token_hash, created_at)
    SELECT id, token_hash, created_at
    FROM revoked_tokens;

    DROP TABLE revoked_tokens;
    ALTER TABLE revoked_tokens_new RENAME TO revoked_tokens;

    COMMIT;
  `);
};

export const initializeDatabase = async (): Promise<void> => {
  const schemaPath = path.resolve(__dirname, "schema.sql");
  const schema = fs.readFileSync(schemaPath, "utf-8");

  await exec(schema);
  await syncRevokedTokensTable();

  console.log("Database schema initialized.");
};

import type { NextFunction, Request, Response } from "express";
import { ZodError } from "zod";

import { AppError } from "../utils/app-error";

export const errorMiddleware = (
  error: Error,
  _req: Request,
  res: Response,
  _next: NextFunction,
) => {
  if (error instanceof ZodError) {
    return res.status(400).json({
      success: false,
      message: "Validation failed",
      issues: error.issues,
    });
  }

  if (error instanceof AppError) {
    return res.status(error.statusCode).json({
      success: false,
      message: error.message,
      ...(error.details ? { details: error.details } : {}),
    });
  }

  return res.status(500).json({
    success: false,
    message: "Internal server error",
  });
};

import type { NextFunction,Request, Response } from "express";

import type { AuthUser } from "../../types/auth.types";
import { taskService } from "./task.service";
import { createTaskSchema, updateTaskSchema } from "./task.validation";

const getUser = (req: Request): AuthUser => req.user as AuthUser;

export const taskController = {
  async list(req: Request, res: Response, next: NextFunction) {
    try {
      const tasks = await taskService.list(getUser(req));
      return res.status(200).json(tasks);
    } catch (error) {
      next(error);
    }
  },

  async getSingle(req: Request, res: Response, next: NextFunction) {
    try {
      const taskId = Number(req.params.id);
      const task = await taskService.getById(getUser(req), taskId);
      return res.status(200).json(task);
    } catch (error: any) {
      if (error.message === "Task not found") {
        return res.status(404).json({ message: "Task not found" });
      }
      next(error);
    }
  },

  async create(req: Request, res: Response, next: NextFunction) {
    try {
      const input = createTaskSchema.parse(req.body);
      const task = await taskService.create(getUser(req), input);
      return res.status(201).json(task);
    } catch (error) {
      next(error);
    }
  },

  async update(req: Request, res: Response, next: NextFunction) {
    try {
      const taskId = Number(req.params.id);
      const input = updateTaskSchema.parse(req.body);
      const task = await taskService.update(getUser(req), taskId, input);
      return res.status(200).json(task);
    } catch (error: any) {
      if (error.message === "Task not found") {
        return res.status(404).json({ message: "Task not found" });
      }
      next(error);
    }
  },

  async remove(req: Request, res: Response, next: NextFunction) {
    try {
      const taskId = Number(req.params.id);
      await taskService.remove(getUser(req), taskId);
      return res.status(204).send();
    } catch (error: any) {
      if (error.message === "Task not found") {
        return res.status(404).json({ message: "Task not found" });
      }
      next(error);
    }
  },
};

import { db } from "../config/db";
import type {
  CreateTaskInput,
  Task,
  TaskStatus,
  UpdateTaskInput,
} from "../types/task.types";

const mapTaskRow = (row: any): Task => ({
  id: Number(row.id),
  title: String(row.title),
  description: String(row.description),
  status: row.status as TaskStatus,
  ownerId: Number(row.owner_id),
  createdAt: String(row.created_at),
  updatedAt: String(row.updated_at),
});

const getOne = <T>(sql: string, params: unknown[] = []): Promise<T | undefined> =>
  new Promise((resolve, reject) => {
    db.get(sql, params, (error, row) => {
      if (error) {
        reject(error);
        return;
      }

      resolve(row as T | undefined);
    });
  });

const getAll = <T>(sql: string, params: unknown[] = []): Promise<T[]> =>
  new Promise((resolve, reject) => {
    db.all(sql, params, (error, rows) => {
      if (error) {
        reject(error);
        return;
      }

      resolve((rows as T[]) ?? []);
    });
  });

const run = (
  sql: string,
  params: unknown[] = [],
): Promise<{ lastID: number; changes: number }> =>
  new Promise((resolve, reject) => {
    db.run(sql, params, function onRun(error) {
      if (error) {
        reject(error);
        return;
      }

      resolve({ lastID: this.lastID, changes: this.changes });
    });
  });

export const taskRepository = {
  async findAll(): Promise<Task[]> {
    const rows = await getAll<any>(
      `SELECT id, title, description, status, owner_id, created_at, updated_at
       FROM tasks
       ORDER BY id DESC`,
    );
    return rows.map(mapTaskRow);
  },

  async findAllByOwnerId(ownerId: number): Promise<Task[]> {
    const rows = await getAll<any>(
      `SELECT id, title, description, status, owner_id, created_at, updated_at
       FROM tasks
       WHERE owner_id = ?
       ORDER BY id DESC`,
      [ownerId],
    );

    return rows.map(mapTaskRow);
  },

  async findById(id: number): Promise<Task | undefined> {
    const row = await getOne<any>(
      `SELECT id, title, description, status, owner_id, created_at, updated_at
       FROM tasks
       WHERE id = ?`,
      [id],
    );

    return row ? mapTaskRow(row) : undefined;
  },

  async create(ownerId: number, input: CreateTaskInput): Promise<Task> {
    const result = await run(
      `INSERT INTO tasks (title, description, status, owner_id)
       VALUES (?, ?, ?, ?)`,
      [input.title, input.description, input.status ?? "todo", ownerId],
    );

    const task = await this.findById(result.lastID);

    if (!task) {
      throw new Error("Task could not be created");
    }

    return task;
  },

  async update(id: number, input: UpdateTaskInput): Promise<Task | undefined> {
    const currentTask = await this.findById(id);

    if (!currentTask) {
      return undefined;
    }

    await run(
      `UPDATE tasks
       SET title = ?,
           description = ?,
           status = ?,
           updated_at = CURRENT_TIMESTAMP
       WHERE id = ?`,
      [
        input.title ?? currentTask.title,
        input.description ?? currentTask.description,
        input.status ?? currentTask.status,
        id,
      ],
    );

    return this.findById(id);
  },

  async delete(id: number): Promise<boolean> {
    const result = await run("DELETE FROM tasks WHERE id = ?", [id]);

    return result.changes > 0;
  },
};

import { describe, it, expect } from "vitest";
